def can_reach(graph, start, target):
    seen = {start}
    todo = [start]
    while todo:
        node = todo.pop()
        if node == target:
            return True
        for nxt in graph[node]:
            if nxt not in seen:
                seen.add(nxt)
                todo.append(nxt)
    return False

